# Cache-release checks use monotonic version comparison, not a brittle allowlist.
def _sw_version(path, prefix):
 try:
  m=re.search(re.escape(prefix)+r'v(\d+)\.(\d+)',path.read_text())
  return (int(m.group(1)),int(m.group(2))) if m else (0,0)
 except Exception:return (0,0)
SW_BUILDER=_sw_version(ROOT/'sw.js','sc-builder-')
# V12.70: the client deployment was renamed gosa -> gosaportal. Resolve it once,
# here, instead of hard-coding a folder that no longer exists (which either
# crashed the audit or silently switched its checks off).
CLIENT_DIR = next((d for d in (ROOT.parent/'gosaportal', ROOT.parent/'gosa', ROOT.parent/'schoolconnectdemo')
                   if (d/'sw.js').exists()), None)
CLIENT_SW = (CLIENT_DIR/'sw.js') if CLIENT_DIR else None
SW_CLIENT=_sw_version(CLIENT_SW,'sc-client-') if CLIENT_SW else (0,0)
def sw_at_least(v):
 major,minor=map(int,v.split('.'))
 return SW_BUILDER >= (major,minor) and (CLIENT_SW is None or SW_CLIENT >= (major,minor))
fail=[]; passed=[]
def sqlpack(path):
    '''Read a SQL pack — or, when it has been folded into the complete schema,
    read the complete schema instead.

    V12.70: the project standard is now ONE SQL file (database/complete-schema.sql);
    the 70-odd per-version packs were consolidated into it and deleted. These
    checks assert "this DDL landed", which is still exactly what we want to
    know — the object simply lives in the consolidated file now. Before this,
    every one of them crashed the audit with FileNotFoundError.
    '''
    try:
        return pathlib.Path(path).read_text(encoding='utf-8', errors='replace')
    except OSError:
        return schema


def _read(path, default=''):
    '''Read a file, or return `default` when it is absent.
    V12.70: several checks point at sibling repositories that are shipped
    separately (hmg-fleet-console). A missing file used to abort the whole
    audit with FileNotFoundError, so the audit sat broken and unreported;
    a missing file should FAIL its own check, not kill the run.'''
    try:
        return pathlib.Path(path).read_text(encoding='utf-8', errors='replace')
    except OSError:
        return default


def ok(name,cond,detail=''):
 (passed if cond else fail).append((name,detail));print(('OK   ' if cond else 'FAIL ')+name+((' — '+detail) if detail else ''))

# PostgreSQL parser + schema/seed column contract
schema=(ROOT/'database/complete-schema.sql').read_text();seed=(ROOT/'database/demo-seed.sql').read_text()
try:
 from pglast import parse_sql,ast
 st=parse_sql(schema); sd=parse_sql(seed); ok('PostgreSQL parses complete-schema.sql',True,f'{len(st)} statements');ok('PostgreSQL parses demo-seed.sql',True,f'{len(sd)} top-level statements')
 cols={}
 for raw in st:
  n=raw.stmt
  if isinstance(n,ast.CreateStmt) and n.relation:
   t=n.relation.relname;cols.setdefault(t,set()).update(x.colname for x in (n.tableElts or ()) if isinstance(x,ast.ColumnDef))
  elif isinstance(n,ast.AlterTableStmt) and n.relation:
   t=n.relation.relname
   for c in n.cmds or ():
    if isinstance(c.def_,ast.ColumnDef):cols.setdefault(t,set()).add(c.def_.colname)
 # Include the seed's session temporary table.
 cols['sc_demo_ids']={'role','id'}
 issues=[]
 for m in re.finditer(r'insert\s+into\s+(?:public\.)?(\w+)\s*\(([^)]*)\)',seed,re.I|re.S):
  t=m.group(1); names=[x.strip().strip('"').lower() for x in m.group(2).split(',')];missing=[x for x in names if x not in cols.get(t,set())]
  if t not in cols: issues.append(f'line {seed.count(chr(10),0,m.start())+1}: missing table {t}')
  elif missing: issues.append(f'line {seed.count(chr(10),0,m.start())+1}: {t} missing {missing}')
 ok('Every demo-seed INSERT column exists in complete schema',not issues,'; '.join(issues[:8]))
 complete_indexes={raw.stmt.idxname for raw in st if isinstance(raw.stmt,ast.IndexStmt) and raw.stmt.idxname};focused_ddl=[]
 for fp in sorted((ROOT/'database').glob('*.sql')):
  if fp.name in ('complete-schema.sql','demo-users.sql','demo-seed.sql'):continue
  for raw in parse_sql(fp.read_text()):
   n=raw.stmt
   if isinstance(n,ast.CreateStmt) and n.relation:
    t=n.relation.relname
    if t not in cols:focused_ddl.append(f'{fp.name}:table:{t}')
    for x in n.tableElts or ():
     if isinstance(x,ast.ColumnDef) and x.colname and x.colname not in cols.get(t,set()):focused_ddl.append(f'{fp.name}:{t}.{x.colname}')
   elif isinstance(n,ast.AlterTableStmt) and n.relation:
    t=n.relation.relname
    for c in n.cmds or ():
     if isinstance(c.def_,ast.ColumnDef) and c.def_.colname and c.def_.colname not in cols.get(t,set()):focused_ddl.append(f'{fp.name}:{t}.{c.def_.colname}')
   elif isinstance(n,ast.IndexStmt) and n.idxname and n.idxname not in complete_indexes:
    # V12.70 — an index that a LATER pack deliberately dropped and replaced is
    # not missing; it was superseded. assignment_scores_cbt_unique is the case:
    # v12.10/11/12 created it, then the final schema replaced it with the same
    # guarantee under correct partial-index shape
    # (assignment_scores_assignment_unique / assignment_scores_cbt_exam_id_idx).
    # Treat "explicitly dropped in the complete schema" as superseded.
    if re.search(r'drop\s+index\s+if\s+exists\s+' + re.escape(n.idxname), schema, re.I):
     continue
    focused_ddl.append(f'{fp.name}:index:{n.idxname}')
 ok('Complete schema contains every focused-upgrade table, column and index',not focused_ddl,'; '.join(focused_ddl[:8]))
except Exception as e:
 ok('PostgreSQL parser available and SQL valid',False,str(e))

# Complete-schema self-sufficiency and client contract.
complete_functions=re.findall(r'create\s+(?:or\s+replace\s+)?function\s+public\.([a-zA-Z0-9_]+)',schema,re.I)
