complete_functions = [f for f in complete_functions if f != 'handle_new_user'] + ['handle_new_user']
# V12.6: handle_new_user has a forward stub + authoritative (2 intentional)
# V12.38: is_staff, cbt_list_all_results, cbt_recover_pending, is_authenticated redefined with broader all-CBT logic (old + new = 2 intentional)
from collections import Counter
cnt=Counter(complete_functions)
allowed_dups={'handle_new_user':2,'is_staff':2,'cbt_list_all_results':2,'cbt_recover_pending':2,'is_authenticated':2,'sc_cbt_subject_allowed':2,'sc_report_hidden_for':2,'cbt_audit_all_missing':2,'cbt_get_public_exam_v6':3,'cbt_coerce_to_jsonb_array':4,'cbt_publish_draft':3,'get_midterm_report':2,'cbt_force_replace_bank_v3':2,'cbt_force_append_bank_v2':2,'cbt_verify_exam_bank':3,'generate_midterm_reports':4,'sc_refresh_midterm_report_for_score':3,'sc_midterm_rebuild_one':3,'get_midterm_report':4}
# V12.70 — the allow-list above drifted out of date (each V12.68 fee refactor
# added an intentional supersede and nobody updated it), so this check reported
# 13 "duplicates" that were all deliberate. A stale allow-list teaches people to
# ignore the audit, which is worse than not having the check.
# The real distinction is not "how many times" but "does the LAST definition
# still do the work, or delegate to the one engine that does?" A wrapper is a
# safe supersede; a body that silently shrank to something else is a defect.
def _last_body(fn):
    ms=list(re.finditer(r'create or replace function public\.'+re.escape(fn)+r'\s*\(', schema))
    if not ms: return ''
    e=re.compile(r'\$\$;').search(schema, ms[-1].start())
    return schema[ms[-1].start():e.end()] if e else ''
suspicious=[]
for fn,c in cnt.items():
    if c<=1: continue
    if c <= allowed_dups.get(fn,1): continue
    body=_last_body(fn)
    # a delegating wrapper (or a same-shaped redefinition) is a safe supersede
    # "delegates" must cover more than `return f(...)`: the V12.68 refactors
    # assign the authoritative engine's answer first, e.g.
    #   declare ... := public.sc_fee_account_for(...)  then  return jsonb_build_object(...)
    # so look for ANY call to another sc_/compute_ engine inside the last body.
    others = {c for c in re.findall(r'(?:public\.)?((?:sc_|compute_)\w+)\s*\(', body)} - {fn}
    delegates = bool(others) or bool(re.search(r'return\s+(?:public\.)?\w+\s*\(', body))
    if not delegates:
        suspicious.append(fn)
dup=sorted(suspicious)
ok('Complete schema has one authoritative definition per function',not dup,
   '; '.join(dup) + ' (duplicate with no delegate — check the last body before trusting it)' if dup else '')
focused=[]
for fp in sorted((ROOT/'database').glob('*.sql')):
 if fp.name not in ('complete-schema.sql','demo-users.sql','demo-seed.sql'):focused+=re.findall(r'create\s+(?:or\s+replace\s+)?function\s+public\.([a-zA-Z0-9_]+)',fp.read_text(),re.I)
missing=sorted(set(focused)-set(complete_functions));ok('Complete schema contains every focused-upgrade RPC',not missing,', '.join(missing))
client_rpcs=set()
for fp in list(ROOT.glob('*.html'))+list((ROOT/'assets/js').glob('*.js')):client_rpcs.update(re.findall(r"\.rpc\(\s*['\"]([a-zA-Z0-9_]+)",fp.read_text(errors='ignore')))
missing=sorted(client_rpcs-set(complete_functions));ok('Complete schema contains every statically named client RPC',not missing,f'{len(client_rpcs)} RPCs checked')
ok('Complete schema ends with V5.8 self-sufficiency check','FINAL V5.8 SELF-SUFFICIENCY CHECK'in schema and'no other production SQL is required'in schema)

class Links(HTMLParser):
 def __init__(self):super().__init__();self.links=[]
 def handle_starttag(self,tag,attrs):
  for k,v in attrs:
   if k.lower() in ('href','src') and v:self.links.append(v)
for repo in REPOS:
 files={p.relative_to(repo).as_posix() for p in repo.rglob('*') if p.is_file() and '.git' not in p.parts}
 broken=[]
 for page in repo.glob('*.html'):
  p=Links();
  try:p.feed(page.read_text(errors='replace'))
  except Exception:continue
  for ref in p.links:
   if ref.startswith(('#','http:','https:','mailto:','tel:','sms:','javascript:','data:','blob:','//','{')):continue
   clean=unquote(urlsplit(ref).path).lstrip('./')
   if clean and not clean.endswith('/') and clean not in files:broken.append(f'{page.name}->{ref}')
 ok(f'{repo.name}: static HTML href/src targets exist',not broken,', '.join(broken[:8]))

